<?php
require_once 'config.php';$admin_id=require_admin($conn);$ready=table_exists($conn,'product_reviews');
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();if(!$ready){flash('error','Спочатку імпортуйте upgrade_v3.sql.');redirect_to('admin_reviews.php');}
 $id=(int)($_POST['review_id']??0);$action=$_POST['action']??'';
 $q=$conn->prepare('SELECT id FROM product_reviews WHERE id=?');$q->bind_param('i',$id);$q->execute();
 if(!$q->get_result()->num_rows){flash('error','Відгук не знайдено.');redirect_to('admin_reviews.php');}
 if(in_array($action,['approve','reject'],true)){$status=$action==='approve'?'approved':'rejected';$q=$conn->prepare('UPDATE product_reviews SET status=? WHERE id=?');$q->bind_param('si',$status,$id);$q->execute();flash('success','Статус відгуку оновлено.');}
 elseif($action==='reply'){$reply=trim((string)($_POST['reply']??''));if(mb_strlen($reply)>1500){flash('error','Відповідь занадто довга.');}else{$q=$conn->prepare('UPDATE product_reviews SET admin_reply=? WHERE id=?');$q->bind_param('si',$reply,$id);$q->execute();flash('success','Відповідь збережено.');}}
 elseif($action==='delete'){$q=$conn->prepare('DELETE FROM product_reviews WHERE id=?');$q->bind_param('i',$id);$q->execute();flash('success','Відгук видалено.');}
 redirect_to('admin_reviews.php?status='.urlencode($_POST['back_status']??'pending'));
}
$status=$_GET['status']??'pending';if(!in_array($status,['pending','approved','rejected','all'],true))$status='pending';
$reviews=[];$counts=['pending'=>0,'approved'=>0,'rejected'=>0];
if($ready){
 foreach($conn->query('SELECT status,COUNT(*) n FROM product_reviews GROUP BY status') as $r)$counts[$r['status']]=(int)$r['n'];
 if($status==='all')$reviews=$conn->query('SELECT r.*,u.name AS user_name,p.name AS product_name FROM product_reviews r JOIN users u ON u.id=r.user_id JOIN products p ON p.id=r.product_id ORDER BY r.created_at DESC LIMIT 100')->fetch_all(MYSQLI_ASSOC);
 else{$q=$conn->prepare('SELECT r.*,u.name AS user_name,p.name AS product_name FROM product_reviews r JOIN users u ON u.id=r.user_id JOIN products p ON p.id=r.product_id WHERE r.status=? ORDER BY r.created_at DESC LIMIT 100');$q->bind_param('s',$status);$q->execute();$reviews=$q->get_result()->fetch_all(MYSQLI_ASSOC);}
}
?>
<!doctype html><html lang="uk"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Модерація відгуків · flora.atelier</title><link rel="stylesheet" href="css/admin_style.css"><link rel="stylesheet" href="css/flor-admin-v8.css"></head><body><?php require 'admin_header.php';?><div class="admin-page-head"><div><span class="admin-eyebrow">ДОВІРА КЛІЄНТІВ</span><h1>Відгуки <em>♡</em></h1><p>Модеруй коментарі та відповідай покупцям прямо тут.</p></div></div>
<?php if(!$ready):?><div class="admin-banner">Таблиця відгуків ще не створена. Імпортуйте <b>upgrade_v3.sql</b> у phpMyAdmin.</div><?php else:?>
<div class="admin-tabs"><a class="<?=$status==='pending'?'active':''?>" href="?status=pending">Очікують (<?=$counts['pending']?>)</a><a class="<?=$status==='approved'?'active':''?>" href="?status=approved">Опубліковані (<?=$counts['approved']?>)</a><a class="<?=$status==='rejected'?'active':''?>" href="?status=rejected">Відхилені (<?=$counts['rejected']?>)</a><a class="<?=$status==='all'?'active':''?>" href="?status=all">Усі</a></div>
<div class="review-admin-list"><?php if(!$reviews):?><div class="admin-empty admin-card">У цій категорії поки немає відгуків.</div><?php endif;?><?php foreach($reviews as $r):?><article class="admin-card admin-review"><div class="review-admin-head"><div><div class="admin-eyebrow">ВІДГУК №<?=(int)$r['id']?> · <?=e($r['created_at'])?></div><h2><?=e($r['user_name'])?> <small>про <a href="view_page.php?pid=<?=(int)$r['product_id']?>" target="_blank" rel="noopener"><?=e($r['product_name'])?> ↗</a></small></h2></div><span class="status-pill <?=e($r['status'])?>"><?=e(['pending'=>'На перевірці','approved'=>'Опубліковано','rejected'=>'Відхилено'][$r['status']])?></span></div><div class="admin-stars"><?=str_repeat('★',(int)$r['rating']).str_repeat('☆',5-(int)$r['rating'])?></div><p><?=nl2br(e($r['review_text']))?></p><div class="review-controls"><form method="post"><?=csrf_input()?><input type="hidden" name="review_id" value="<?=(int)$r['id']?>"><input type="hidden" name="back_status" value="<?=e($status)?>"><button class="admin-btn" name="action" value="approve">✓ Опублікувати</button><button class="admin-btn light" name="action" value="reject">Відхилити</button><button class="text-danger" type="submit" name="action" value="delete" data-confirm="Назавжди видалити цей відгук?">Видалити</button></form></div><form method="post" class="reply-form"><?=csrf_input()?><input type="hidden" name="review_id" value="<?=(int)$r['id']?>"><input type="hidden" name="back_status" value="<?=e($status)?>"><label>Відповідь магазину<textarea name="reply" maxlength="1500" placeholder="Подякуйте за враження або допоможіть з питанням…"><?=e($r['admin_reply']??'')?></textarea></label><button type="submit" name="action" value="reply" class="admin-btn outline">Зберегти відповідь ↗</button></form></article><?php endforeach;?></div>
<?php endif;?><?php require 'admin_footer.php';?></body></html>
